unsafe fn Mask_calcRunLengthV(
    mut width: c_int,
    mut frame: *mut c_uchar,
    mut runLength: *mut c_int,
) -> c_int {
    let mut head: c_int = 0;
    let mut prev: c_uchar = 0;
    let width_usize = width as usize;
    let run_len_usize = width_usize.wrapping_add(1);

    // SAFETY: `width` is the caller-provided logical extent for this scan; this
    // function already unconditionally reads `frame[0]`, so callers must provide
    // a non-null `frame` pointing to at least the strided positions used here,
    // including indices `i * width` for `0 <= i < width`. No other reference is
    // created to this memory in this region.
    let frame = unsafe { core::slice::from_raw_parts(frame as *const c_uchar, width_usize * width_usize) };
    // SAFETY: the output uses at most `width + 1` entries (optional leading -1
    // plus one run per scanned row). Callers must provide non-null writable
    // storage for that many `c_int`s, and no other reference aliases it here.
    let run_length = unsafe { core::slice::from_raw_parts_mut(runLength, run_len_usize) };

    if frame[0] as c_int & 1 as c_int != 0 {
        run_length[0] = -(1 as c_int);
        head = 1 as c_int;
    } else {
        head = 0 as c_int;
    }
    run_length[head as usize] = 1 as c_int;
    prev = frame[0];

    let mut i: c_int = 1 as c_int;
    while i < width {
        let pixel = frame[(i * width) as usize];
        if (pixel as c_int ^ prev as c_int) & 1 as c_int != 0 {
            head += 1;
            run_length[head as usize] = 1 as c_int;
            prev = pixel;
        } else {
            run_length[head as usize] += 1;
        }
        i += 1;
    }
    return head + 1 as c_int;
}

